#!/usr/bin/env python3
"""Sum up 19 November's world news in one image.

Writes the finished front page (entry.png, 1024x1024) to the output
directory: $MAKEFUN_OUTPUT_DIR, else /output if it exists, else
./output. The image bytes are embedded below as zlib-compressed
base64 in five literals; decoding is deterministic, so every run
writes byte-identical output. Standard library only, no network.
"""
import base64
import os
import zlib

DATA = (
    ""
    ""
    ""
    ""
    ""
)


def main():
    raw = zlib.decompress(base64.b64decode("".join(DATA)))
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if not out_dir:
        out_dir = "/output" if os.path.isdir("/output") else "output"
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.png"), "wb") as fh:
        fh.write(raw)


if __name__ == "__main__":
    main()
